import {bindAdminDialogs} from './interaction.mjs';
import {prepareCatalogue} from './catalogue-presentation.mjs';
import {prepareSalesContent} from './sales-content-presentation.mjs';
// One authenticated shell over the existing business controllers and repositories.
export const adminRoutes=[
 ['inventory','Inventory','/admin/?view=inventory','Workspace'],['overview','Overview','/admin/overview/','Workspace'],
 ['assemblies','Products & assemblies','/admin/?view=assemblies','Catalogue'],['kits','Wiring kits','/admin/wiring-kit-master/','Catalogue'],['catalogue','Catalogue settings','/admin/catalogue-settings/','Catalogue'],
 ['orders','Orders & fulfilment','/admin/orders/','Sales'],['external','Marketplace order','/admin/orders/?new=external','Sales'],['aftercare','Customer aftercare','/admin/orders/?view=aftercare','Sales'],['attempts','Checkout attempts','/admin/orders/?view=attempts','Sales'],
 ['conjure','Conjure website editor','/admin/conjure/','Website'],['articles','Articles & revisions','/admin/hub-cms/','Website'],['media','Media library','/admin/hub-media/','Website'],['news','News','/admin/site-operations/#news','Website'],['announcements','Announcements','/admin/site-operations/#announcements','Website'],
 ['operations','Site operations','/admin/site-operations/','Operations'],['destinations','Commercial / eBay','/admin/site-operations/#commercial-destinations','Operations'],['forge','Circuit FORGE ↗','/circuit-forge/','Instruments'],
 ['templates','Email template studio','/admin/email-templates/','Communications'],['email','Email preview','/admin/email-preview/','Communications'],['maintenance','Settings & exports','/admin/?view=maintenance','System']
].map(([id,label,href,group])=>({id,label,href,group}));
export const workspaceDescriptions={inventory:'Components, pricing and shared stock. Your existing inventory tools, in one workspace.',overview:'Current operational priorities across your workshop.',assemblies:'Product assemblies and wiring kit definitions.',kits:'Plan components, costs and production without reserving stock.',catalogue:'Manage catalogue labels and reusable options.',orders:'Manage customer orders, production and dispatch.',external:'Record an external marketplace order using the existing order workflow.',aftercare:'Customer follow-up and delivery support.',attempts:'Review existing checkout attempts.',conjure:'Edit supported website content. Drafts and publication keep their existing safeguards.',articles:'Structured articles, SEO and revisions. Use Conjure for visual editing.',media:'Approved assets and private article references.',news:'Draft, schedule and publish News.',announcements:'Review the shared announcement and its priority rules.',operations:'Ordering availability and schedules. Existing orders continue.',destinations:'Verified commercial destinations and marketplace links.',forge:'Open the existing Circuit FORGE specialist workbench.',maintenance:'Private migration exports and occasional maintenance.',templates:'Edit, preview and publish versioned customer email wording.',email:'Preview transactional templates without sending an email.'};
export function workspaceFor(location){const p=location.pathname,q=new URLSearchParams(location.search);if(p==='/admin/'||p==='/admin/index.html'||p.startsWith('/admin/command/'))return q.get('view')==='assemblies'?'assemblies':q.get('view')==='maintenance'?'maintenance':'inventory';if(p.startsWith('/admin/orders/'))return q.get('new')==='external'?'external':q.get('view')==='aftercare'?'aftercare':q.get('view')==='attempts'?'attempts':'orders';if(p.startsWith('/admin/site-operations/'))return {'#news':'news','#announcements':'announcements','#commercial-destinations':'destinations'}[location.hash]||'operations';return adminRoutes.find(r=>new URL(r.href,'https://site.test').pathname===p)?.id||'overview';}
export function uiNode(d,tag,text,className){const n=d.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
export function statusBadge(d,text,tone='neutral'){const n=uiNode(d,'span',text,'admin-badge');n.dataset.tone=tone;return n;}
const shells=new WeakMap();
export function mountAdminSkin(d){
 d.body.dataset.commandSkin='nocturne';
 if(!d.querySelector('link[data-admin-styles]')){const css=d.createElement('link');css.rel='stylesheet';const url=new URL('./application.css',import.meta.url);url.search=new URL(import.meta.url).search;css.href=url.href;css.dataset.adminStyles='command';d.head.append(css);}
}
export function concealAdminShell(d){shells.get(d)?.close(false);for(const dialog of d.querySelectorAll('dialog[open]'))dialog.close();d.dispatchEvent(new d.defaultView.Event('admin:conceal'));}
const icons={Workspace:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',Catalogue:'M4 5h16v15H4z M8 2v6 M16 2v6 M4 11h16',Sales:'M4 4h16v16H4z M8 9h8 M8 13h6 M8 17h4',Website:'M3 4h18v16H3z M3 9h18 M8 9v11',Operations:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',Instruments:'M4 18l10-10 2 2L6 20z M14 8l4-5 3 3-5 4',Communications:'M3 5h18v14H3z M3 5l9 8 9-8',System:'M5 5h14v14H5z M9 9h6v6H9z'};
function icon(d,group){const svg=d.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');svg.classList.add('admin-nav-icon');const path=d.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',icons[group]||icons.Workspace);svg.append(path);return svg;}
export function mountAdminShell(d,signOut){
 const main=d.querySelector('main:not(.admin-access-gate)');if(!main)return null;mountAdminSkin(d);
 const existing=shells.get(d);if(existing){d.querySelector('[data-admin-session] .admin-lock')?.remove();d.querySelector('[data-admin-session]').append(signOut);existing.close(false);return existing.top;}
 const conjure=d.body.hasAttribute('data-conjure-app');d.body.dataset.adminApp='command';d.body.dataset.adminWorkspace=workspaceFor(d.location);main.classList.add('admin-main');if(!main.id)main.id='main';
 d.querySelectorAll('body > .site-header,body > #mobile-nav,body > footer,.admin-workspaces,.admin-navigation,nav.admin-tabs').forEach(n=>n.remove());
 const exit=a=>{if(conjure)a.dataset.conjureExit='';return a;};
 const top=uiNode(d,'header',undefined,'admin-app-topbar');top.dataset.adminTopbar='true';
 const toggle=uiNode(d,'button',undefined,'admin-icon-button');toggle.type='button';toggle.append(uiNode(d,'span','☰','admin-menu-glyph'),uiNode(d,'span','Menu','admin-menu-label'));toggle.setAttribute('aria-label','Open workspace navigation');toggle.setAttribute('aria-controls','admin-sidebar');toggle.setAttribute('aria-expanded','false');toggle.dataset.adminMenu='true';
 const brand=exit(uiNode(d,'a',undefined,'admin-app-brand'));brand.href='/admin/';const mark=uiNode(d,'span','AI','admin-brand-mark');mark.setAttribute('aria-hidden','true');const word=uiNode(d,'span',undefined,'admin-brand-word');word.append(uiNode(d,'strong','COMMAND'),uiNode(d,'small','APPARITION INSTRUMENTS'));brand.append(mark,word);
 const session=uiNode(d,'div',undefined,'admin-app-session');session.dataset.adminSession='true';const account=uiNode(d,'a','Account');account.href='/account/';account.target='_blank';account.rel='noopener';session.append(account,signOut);top.append(toggle,brand,session);
 const sidebar=uiNode(d,'aside',undefined,'admin-app-sidebar');sidebar.id='admin-sidebar';sidebar.setAttribute('aria-label','Workspace navigation');const nav=uiNode(d,'nav');nav.setAttribute('aria-label','Admin workspaces');let group=null;
 for(const r of adminRoutes){if(r.group!==group){group=r.group;nav.append(uiNode(d,'h2',group,'admin-nav-group'));}const link=exit(uiNode(d,'a',undefined,'admin-nav-item'));link.href=r.href;link.dataset.workspace=r.id;link.append(icon(d,r.group),uiNode(d,'span',r.label));if(['inventory','assemblies','orders','kits'].includes(r.id))link.dataset.adminDestination=r.id==='kits'?'master':r.id;if(r.id==='conjure')link.classList.add('admin-conjure-entry');nav.append(link);}
 const foot=uiNode(d,'div',undefined,'admin-sidebar-foot'),website=exit(uiNode(d,'a','Return to website ↗'));website.href='/';foot.append(website,uiNode(d,'small','APPARITION / WORKSHOP CONTROL'));sidebar.append(nav,foot);
 const backdrop=uiNode(d,'button',undefined,'admin-nav-backdrop');backdrop.type='button';backdrop.tabIndex=-1;backdrop.setAttribute('aria-label','Close workspace navigation');backdrop.hidden=true;main.before(top,sidebar,backdrop);
 const invoice=main.id==='invoice';const chrome=invoice?uiNode(d,'section',undefined,'admin-main admin-route-intro'):main;if(invoice)main.before(chrome);
 let header=conjure||invoice?null:main.querySelector('.admin-title');if(!header){header=uiNode(d,'div',undefined,'admin-title');const heading=conjure||invoice?uiNode(d,'h1',invoice?'Invoice':'Conjure'):main.querySelector('h1')||uiNode(d,'h1','Workspace');header.append(heading);chrome.prepend(header);}header.classList.add('admin-page-header');header.querySelector('.eyebrow')?.remove();main.querySelector(':scope > .eyebrow')?.remove();
 const breadcrumb=uiNode(d,'nav',undefined,'admin-breadcrumb');breadcrumb.setAttribute('aria-label','Breadcrumb');const home=exit(uiNode(d,'a','COMMAND'));home.href='/admin/';const slash=uiNode(d,'span','/');slash.setAttribute('aria-hidden','true');const context=uiNode(d,'span');context.setAttribute('aria-current','location');breadcrumb.append(home,slash,context);header.before(breadcrumb);
 const description=uiNode(d,'p',undefined,'admin-page-description');description.dataset.workspaceDescription='true';header.after(description);prepareCatalogue(d);prepareSalesContent(d);
 const paint=()=>{const id=workspaceFor(d.location),route=adminRoutes.find(r=>r.id===id);d.body.dataset.adminWorkspace=id;for(const a of nav.querySelectorAll('a')){if(a.dataset.workspace===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}context.textContent=(route?.group||'Workspace')+' / '+(route?.label||'Workspace');description.textContent=workspaceDescriptions[id]||'';if(d.location.pathname.includes('/site-operations/')&&route)header.querySelector('h1').textContent=route.label;};paint();d.defaultView.addEventListener('hashchange',paint);
 const narrow=d.defaultView.matchMedia('(max-width:1050px)');let open=false;
 const sync=()=>{sidebar.inert=narrow.matches&&!open;main.inert=narrow.matches&&open;chrome.inert=narrow.matches&&open;session.inert=narrow.matches&&open;backdrop.hidden=!narrow.matches||!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close workspace navigation':'Open workspace navigation');d.body.toggleAttribute('data-admin-menu-open',open);if(narrow.matches&&open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');}else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');}};
 const close=(returnFocus=false)=>{open=false;sync();if(returnFocus&&toggle.isConnected)toggle.focus();};sync();narrow.addEventListener('change',()=>close(false));toggle.addEventListener('click',()=>{open=!open;sync();if(open&&narrow.matches)(nav.querySelector('[aria-current=page]')||nav.querySelector('a'))?.focus();});backdrop.addEventListener('click',()=>close(true));sidebar.addEventListener('click',e=>{if(e.target.closest('a'))close(false);});
 d.addEventListener('keydown',event=>{if(!open||!narrow.matches)return;if(event.key==='Escape'){event.preventDefault();close(true);}else if(event.key==='Tab'){const controls=[toggle,...sidebar.querySelectorAll('a[href],button:not([disabled])')],first=controls[0],last=controls.at(-1);if(event.shiftKey&&d.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&d.activeElement===last){event.preventDefault();first.focus();}}});
 const size=()=>d.body.style.setProperty('--admin-topbar-height',top.getBoundingClientRect().height+'px');const Observer=d.defaultView.ResizeObserver;if(typeof Observer==='function')new Observer(size).observe(top);size();bindAdminDialogs(d);shells.set(d,{top,close});return top;
}
